// US$ per 1 million tokens, by model. Add a row here when you switch WRITER_MODEL or REVIEW_MODEL.
// This runs BEFORE any run is claimed or sent to Claude: a model without a price stops the
// execution here, so no call is ever made whose cost we could not log.
const PRICES = {
  'claude-opus-5-5': { input: 4, output: 20 },
  'claude-sonnet-5-5': { input: 2, output: 10 },
  'claude-haiku-5-5': { input: 0.1, output: 0.5 },
};
// Opus and Sonnet requests ask for server-side fallbacks (header + body field).
const WITH_FALLBACKS = ['claude-opus-5-5', 'claude-sonnet-5-5'];

const pick = (envName) => {
  const model = $env[envName];
  const price = PRICES[model];
  if (!price) {
    throw new Error(`No price for model "${model}" (${envName}). Add it to the table in "Look up model prices". Nothing was sent to Claude.`);
  }
  return { model, input_usd_per_mtok: price.input, output_usd_per_mtok: price.output, fallbacks: WITH_FALLBACKS.includes(model) };
};
// Writer + reviewer rounds per attempt. Default 3; kept between 1 and 5 so a typo cannot multiply the spend.
const raw = String($env.GENERATION_MAX_ROUNDS ?? '').trim();
const n = /^\d+$/.test(raw) ? Number(raw) : 0;
const max_rounds = n >= 1 ? Math.min(n, 5) : 3;
// prices: the whole table, so each cost is priced by the model that actually answered (a server-side
// fallback can answer with another model).
return [{ json: { writer: pick('WRITER_MODEL'), reviewer: pick('REVIEW_MODEL'), prices: PRICES, max_rounds } }];

