// Everything the writer and the reviewer get, gathered once per execution. Generation only starts
// when the base CV is ready: analysed, and the stored file is the one that was analysed.
const run = $('Claim one run').first().json;
const job = $('Load inputs').first().json;
const res = $json; // the worker's read of the stored documents
const fail = (error, final) => ({ json: { ready: false, run_id: run.id, claimed_at: run.claimed_at, error, final } });

if (!job.job_id) return fail('The job was not found.', true);
if (job.extraction_status !== 'done') return fail("The job's details have not been read yet.", true);
if (!job.cv_id) return fail("Your base CV isn't ready.", true);
const httpOk = typeof res.statusCode === 'number' && res.statusCode >= 200 && res.statusCode < 300;
const documents = httpOk && res.body && Array.isArray(res.body.documents) ? res.body.documents : null;
// The worker did not answer: a failed attempt, tried again later.
if (!documents) return fail('Your base CV file could not be read; it will be tried again.', false);
const stored = documents.find((d) => d.kind === 'cv');
// Replaced since its analysis, or unreadable: the analysed facts would not match the file sent.
if (!stored || stored.contentHash !== job.cv_hash || (!stored.pdfBase64 && !stored.text)) {
  return fail("Your base CV isn't ready.", true);
}

const cv_block = stored.pdfBase64
  ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: stored.pdfBase64 } }
  : { type: 'text', text: '<document>\n' + stored.text + '\n</document>' };
const letter = job.cl_structured;
const inputs = {
  job_id: job.job_id,
  job_ad: job.raw_text ?? '',
  job_facts: { title: job.title, employer: job.employer, advertiser: job.advertiser, shortDescription: job.short_description },
  base_cv_facts: job.cv_structured,
  // The base cover letter goes only as its analysis, never as its text.
  base_cover_letter: letter
    ? { previousTarget: letter.previousTarget ?? null, reusableParagraphs: letter.reusableParagraphs ?? [], toneNotes: letter.toneNotes ?? '' }
    : null,
  company_notes: job.company_notes ?? '',
  other_jobs: Array.isArray(job.other_jobs) ? job.other_jobs : [],
  cv_block,
  cv_id: job.cv_id,
  cv_hash: job.cv_hash,
  cl_id: letter ? job.cl_id : null,
  cl_hash: letter ? job.cl_hash : null,
};
return { json: { ready: true, run_id: run.id, claimed_at: run.claimed_at, round: 1, inputs } };

// The writer's request for this round. On a revision the previous round comes from the run's row
// in the database (returned by the heartbeat), not from an earlier pass through the loop.
const beat = $json; // id, claimed_at (the renewed claim token), round, rounds
const { inputs } = $('Prepare inputs').first().json;
const prompts = $('Writer and reviewer prompts').first().json;
const price = $('Look up model prices').first().json.writer;
const rounds = Array.isArray(beat.rounds) ? beat.rounds : [];
if (rounds.length !== beat.round - 1) {
  throw new Error(`Round ${beat.round} found ${rounds.length} recorded rounds in the run; stopping before calling Claude.`);
}
const prev = rounds[rounds.length - 1] ?? null;

const tagged = (name, value) =>
  `<${name}>\n${typeof value === 'string' ? value : JSON.stringify(value, null, 2)}\n</${name}>`;
const parts = [
  tagged('job_ad', inputs.job_ad),
  tagged('job_facts', inputs.job_facts),
  tagged('base_cv_facts', inputs.base_cv_facts),
  tagged('base_cover_letter', inputs.base_cover_letter ?? 'none'),
  tagged('company_notes', inputs.company_notes),
];
if (prev) {
  const review = prev.review;
  const invented = review.factRulings.filter((r) => r.ruling === 'invented');
  const misspelt = review.spellingRulings.filter((r) => r.ruling === 'misspelt');
  // A review check still open: the reviewer ruled against it (an unmatched skill ruled invented, a word
  // ruled misspelt) or did not rule on it at all. Only an honest_rephrase / ok ruling that names it settles it.
  const settled = (c) => {
    const detail = String(c.detail ?? '').toLowerCase();
    const named = (s) => detail === String(s).toLowerCase() || detail.includes(`"${String(s).toLowerCase()}"`);
    if (c.code === 'unmatched_skill') return review.factRulings.some((r) => r.ruling === 'honest_rephrase' && named(r.text));
    if (c.code === 'possible_misspelling') return review.spellingRulings.some((r) => r.ruling === 'ok' && named(r.word));
    return false;
  };
  parts.push(
    tagged('previous_round', {
      documents: prev.writer,
      failedChecks: prev.checks.filter((c) => c.severity === 'hard' || (c.severity === 'review' && !settled(c))),
      warnings: prev.checks.filter((c) => c.severity === 'warning'),
      failedItems: review.items.filter((i) => !i.pass),
      rulingsAgainst: { facts: invented, spelling: misspelt },
      objections: review.objections,
    }),
  );
}
const today = $now.toFormat('d LLLL yyyy');
parts.push(
  prev
    ? `Today's date is ${today}. Revise the documents in <previous_round>: fix every objection and failed check, and change nothing else.`
    : `Today's date is ${today}. Write the tailored CV and cover letter for this job.`,
);

const headers = { 'anthropic-version': '2026-10-21', 'content-type': 'application/json' };
if (price.fallbacks) headers['anthropic-beta'] = 'server-side-fallback-2026-07-01';
const request = {
  model: price.model,
  max_tokens: 16000,
  output_config: { effort: 'medium', format: { type: 'json_schema', schema: prompts.writer_schema } },
  system: prompts.writer_prompt,
  messages: [{ role: 'user', content: [inputs.cv_block, { type: 'text', text: parts.join('\n\n') }] }],
};
if (price.fallbacks) request.fallbacks = 'default';
return { json: { run_id: beat.id, claimed_at: beat.claimed_at, round: beat.round, job_id: inputs.job_id, headers, request } };

// Flattens the writer's HTTP response into simple fields the IF nodes can check, and works out the cost.
const res = $json; // statusCode + body, or { error } when the request itself failed
const { headers, request, ...state } = $('Build writer request').first().json; // this round: run_id, claimed_at, round, job_id
const lookup = $('Look up model prices').first().json;
const body = res.body && typeof res.body === 'object' ? res.body : {};
const isObject = (v) => !!v && typeof v === 'object' && !Array.isArray(v);
const isString = (v) => typeof v === 'string';
const isStringList = (v) => Array.isArray(v) && v.every(isString);
const isList = (v, item) => Array.isArray(v) && v.every((x) => isObject(x) && item(x));

// The answer is the first "text" block (skip any "thinking" blocks before it).
const textBlock = (body.content ?? []).find((block) => block.type === 'text');
let answer = null;
try {
  // NUL characters are dropped: Postgres cannot store them in jsonb.
  answer = JSON.parse(textBlock?.text ?? '', (k, v) => (typeof v === 'string' ? v.replace(/\u0000/g, '') : v));
} catch {
  answer = null;
}
// The CV and letter themselves are checked field by field by the worker (stage 5b).
const validJson =
  isObject(answer) && answer.templateId === 'standard-ats' && isString(answer.templateReason) &&
  isObject(answer.cv) && isObject(answer.coverLetter) &&
  isObject(answer.keywordCoverage) && isStringList(answer.keywordCoverage.covered) &&
  isList(answer.keywordCoverage.missing, (m) => isString(m.keyword) && isString(m.why)) &&
  isList(answer.changes, (c) => [c.target, c.what, c.why].every(isString)) &&
  isList(answer.stretches, (s) => [s.target, s.text, s.why].every(isString));

const httpOk = typeof res.statusCode === 'number' && res.statusCode >= 200 && res.statusCode < 300;
const stopReason = body.stop_reason ?? null;
let error = null;
if (!httpOk) error = typeof res.statusCode === 'number' ? `The request to Claude failed (HTTP ${res.statusCode}).` : 'The request to Claude failed (no response).';
else if (stopReason === 'refusal') error = 'Claude declined to write the documents.';
else if (stopReason === 'max_tokens') error = "Claude's answer was cut off (max_tokens).";
else if (stopReason !== 'end_turn') error = `Claude stopped unexpectedly (${stopReason ?? 'no stop reason'}).`;
else if (!validJson) error = "The writer's answer was not in the expected format.";

// Cost: priced by the model that answered when the table has it, else by the writer model's price.
const usage = body.usage ?? {};
const has_usage = Number.isInteger(usage.input_tokens) && Number.isInteger(usage.output_tokens);
const model = isString(body.model) && body.model !== '' ? body.model : lookup.writer.model;
const price = lookup.prices[model] ?? { input: lookup.writer.input_usd_per_mtok, output: lookup.writer.output_usd_per_mtok };
const cost_usd = has_usage ? (usage.input_tokens * price.input + usage.output_tokens * price.output) / 1e6 : null;
return {
  json: {
    ...state,
    ok: error === null,
    error,
    final: false,
    writer: error === null ? answer : null,
    purpose: 'write_documents',
    model,
    has_usage,
    input_tokens: has_usage ? usage.input_tokens : null,
    output_tokens: has_usage ? usage.output_tokens : null,
    cost_usd,
  },
};

// Picks the writer's answer up again after its cost was logged (or there was no usage to log): one
// chain, so the cost row is always written before the outcome is looked at.
return { json: $("Read the writer's answer").first().json };

// The worker's check request for this round's documents.
const beat = $json; // id, claimed_at (renewed), round
const written = $("Read the writer's answer").first().json; // this round's writer answer
const { inputs } = $('Prepare inputs').first().json;
if (written.run_id !== beat.id || written.round !== beat.round) throw new Error('The writer answer is not from this round; stopping.');
const w = written.writer;
const body = {
  templateId: w.templateId,
  cv: w.cv,
  coverLetter: w.coverLetter,
  keywordsCovered: w.keywordCoverage.covered,
  job: { title: inputs.job_facts.title, employer: inputs.job_facts.employer, advertiser: inputs.job_facts.advertiser, rawText: inputs.job_ad },
  baseCv: { structured: inputs.base_cv_facts },
  baseCoverLetter: inputs.base_cover_letter ? { structured: inputs.base_cover_letter } : null,
  otherJobs: inputs.other_jobs,
};
return { json: { run_id: beat.id, claimed_at: beat.claimed_at, round: beat.round, job_id: inputs.job_id, writer: w, body } };

// The worker's check results, joined to this round's documents.
const res = $json;
const { body, ...state } = $('Build check request').first().json; // run_id, claimed_at, round, job_id, writer
const httpOk = typeof res.statusCode === 'number' && res.statusCode >= 200 && res.statusCode < 300;
const b = res.body;
const valid = httpOk && !!b && Array.isArray(b.checks) && Number.isInteger(b.cvPages) && Number.isInteger(b.letterPages);
let error = null;
if (!valid) {
  error = res.statusCode === 400
    ? "The writer's documents were not in the expected format."
    : `The document checks could not run (${typeof res.statusCode === 'number' ? `HTTP ${res.statusCode}` : 'no response'}).`;
}
return {
  json: {
    ...state,
    ok: error === null,
    error,
    final: false,
    checks: valid ? b.checks : null,
    cvPages: valid ? b.cvPages : null,
    letterPages: valid ? b.letterPages : null,
  },
};

// The reviewer's request: its own prompt, and only the writer's OUTPUT (never the writer's prompt).
const beat = $json; // id, claimed_at (renewed), round
const checked = $('Read check results').first().json; // this round's documents and checks
const { inputs } = $('Prepare inputs').first().json;
const prompts = $('Writer and reviewer prompts').first().json;
const price = $('Look up model prices').first().json.reviewer;
if (checked.run_id !== beat.id || checked.round !== beat.round) throw new Error('The checks are not from this round; stopping.');

const tagged = (name, value) =>
  `<${name}>\n${typeof value === 'string' ? value : JSON.stringify(value, null, 2)}\n</${name}>`;
const text = [
  tagged('job_ad', inputs.job_ad),
  tagged('job_facts', inputs.job_facts),
  tagged('base_cv_facts', inputs.base_cv_facts),
  tagged('base_cover_letter', inputs.base_cover_letter ?? 'none'),
  tagged('company_notes', inputs.company_notes),
  tagged('documents', checked.writer),
  tagged('code_checks', checked.checks),
  'Review these documents for this job.',
].join('\n\n');

const headers = { 'anthropic-version': '2026-10-21', 'content-type': 'application/json' };
if (price.fallbacks) headers['anthropic-beta'] = 'server-side-fallback-2026-07-01';
const request = {
  model: price.model,
  max_tokens: 8000,
  output_config: { effort: 'medium', format: { type: 'json_schema', schema: prompts.review_schema } },
  system: prompts.review_prompt,
  messages: [{ role: 'user', content: [inputs.cv_block, { type: 'text', text }] }],
};
if (price.fallbacks) request.fallbacks = 'default';
return {
  json: {
    run_id: beat.id,
    claimed_at: beat.claimed_at,
    round: beat.round,
    job_id: inputs.job_id,
    writer: checked.writer,
    checks: checked.checks,
    cvPages: checked.cvPages,
    letterPages: checked.letterPages,
    headers,
    request,
  },
};

// Flattens the reviewer's HTTP response, decides whether the round passed, and works out the cost.
const res = $json; // statusCode + body, or { error } when the request itself failed
const { headers, request, writer, checks, cvPages, letterPages, ...state } = $('Build review request').first().json;
const lookup = $('Look up model prices').first().json;
const body = res.body && typeof res.body === 'object' ? res.body : {};
const isObject = (v) => !!v && typeof v === 'object' && !Array.isArray(v);
const isString = (v) => typeof v === 'string';
const isList = (v, item) => Array.isArray(v) && v.every((x) => isObject(x) && item(x));

// The answer is the first "text" block (skip any "thinking" blocks before it).
const textBlock = (body.content ?? []).find((block) => block.type === 'text');
let a = null;
try {
  // NUL characters are dropped: Postgres cannot store them in jsonb.
  a = JSON.parse(textBlock?.text ?? '', (k, v) => (typeof v === 'string' ? v.replace(/\u0000/g, '') : v));
} catch {
  a = null;
}
const validJson =
  isObject(a) && ['pass', 'fail'].includes(a.verdict) &&
  isList(a.items, (i) => isString(i.id) && typeof i.pass === 'boolean' && isString(i.note)) &&
  isList(a.objections, (o) => [o.target, o.problem, o.fix].every(isString)) &&
  isList(a.factRulings, (r) => isString(r.text) && ['honest_rephrase', 'invented'].includes(r.ruling) && isString(r.why)) &&
  isList(a.spellingRulings, (r) => isString(r.word) && ['ok', 'misspelt'].includes(r.ruling) && (r.fix === null || isString(r.fix))) &&
  isList(a.stretches, (s) => [s.target, s.text, s.why].every(isString));

const httpOk = typeof res.statusCode === 'number' && res.statusCode >= 200 && res.statusCode < 300;
const stopReason = body.stop_reason ?? null;
let error = null;
if (!httpOk) error = typeof res.statusCode === 'number' ? `The request to Claude failed (HTTP ${res.statusCode}).` : 'The request to Claude failed (no response).';
else if (stopReason === 'refusal') error = 'Claude declined to review the documents.';
else if (stopReason === 'max_tokens') error = "Claude's answer was cut off (max_tokens).";
else if (stopReason !== 'end_turn') error = `Claude stopped unexpectedly (${stopReason ?? 'no stop reason'}).`;
else if (!validJson) error = "The reviewer's answer was not in the expected format.";
const ok = error === null;

// A review check is ruled when a ruling names it: a fact ruling for an unmatched skill, a spelling
// ruling for a possible misspelling (the worker quotes the name in its detail, or the detail is the
// word). Any other review check, or one no ruling names, is unruled: the reviewer skipped it.
const named = (detail, s) => {
  const d = String(detail ?? '').toLowerCase();
  const n = String(s).toLowerCase();
  return d === n || d.includes(`"${n}"`);
};
const ruled = (c) => {
  if (c.code === 'unmatched_skill') return a.factRulings.some((r) => named(c.detail, r.text));
  if (c.code === 'possible_misspelling') return a.spellingRulings.some((r) => named(c.detail, r.word));
  return false;
};
const unruled = ok ? checks.filter((c) => c.severity === 'review' && !ruled(c)) : [];

// Passed: verdict pass, every checklist item passes (a "pass" with a failed item contradicts itself),
// no hard check, no invented fact, no misspelt word, and every review check has a ruling.
const passed =
  ok && a.verdict === 'pass' &&
  a.items.every((i) => i.pass) &&
  !checks.some((c) => c.severity === 'hard') &&
  !a.factRulings.some((r) => r.ruling === 'invented') &&
  !a.spellingRulings.some((r) => r.ruling === 'misspelt') &&
  unruled.length === 0;

// Cost: priced by the model that answered when the table has it, else by the reviewer model's price.
const usage = body.usage ?? {};
const has_usage = Number.isInteger(usage.input_tokens) && Number.isInteger(usage.output_tokens);
const model = isString(body.model) && body.model !== '' ? body.model : lookup.reviewer.model;
const price = lookup.prices[model] ?? { input: lookup.reviewer.input_usd_per_mtok, output: lookup.reviewer.output_usd_per_mtok };
const cost_usd = has_usage ? (usage.input_tokens * price.input + usage.output_tokens * price.output) / 1e6 : null;
return {
  json: {
    ...state, // run_id, claimed_at, round, job_id
    ok,
    error,
    final: false,
    review: ok ? a : null,
    passed,
    // What "Record the round" appends to the run's rounds.
    round_record: ok ? { round: state.round, writer, checks, cvPages, letterPages, review: a, passed, unruled } : null,
    purpose: 'review_documents',
    model,
    has_usage,
    input_tokens: has_usage ? usage.input_tokens : null,
    output_tokens: has_usage ? usage.output_tokens : null,
    cost_usd,
  },
};

// Picks the reviewer's answer up again after its cost was logged (or there was no usage to log): one
// chain, so the cost row is always written before the outcome is looked at.
return { json: $("Read the reviewer's answer").first().json };

// After a recorded round: save when it passed or it was the last round; otherwise go round again.
// Everything comes from the run's row in the database.
const row = $json; // id, claimed_at (renewed), round, rounds
const max = $('Look up model prices').first().json.max_rounds;
const rounds = Array.isArray(row.rounds) ? row.rounds : [];
const last = rounds[rounds.length - 1];
if (rounds.length !== row.round || !last || last.round !== row.round) {
  throw new Error(`The run has ${rounds.length} recorded rounds at round ${row.round}; stopping.`);
}
const another = last.passed !== true && row.round < max;
return {
  json: {
    run_id: row.id,
    claimed_at: row.claimed_at,
    round: another ? row.round + 1 : row.round,
    another,
    rounds: another ? [] : rounds,
  },
};

// Picks the round to save from the run's recorded rounds, and builds the version's fields.
const { run_id, claimed_at, rounds } = $json;
const { inputs } = $('Prepare inputs').first().json;
const hard = (r) => r.checks.filter((c) => c.severity === 'hard');
const failedItems = (r) => r.review.items.filter((i) => !i.pass);
const invented = (r) => r.review.factRulings.filter((f) => f.ruling === 'invented');
const misspelt = (r) => r.review.spellingRulings.filter((s) => s.ruling === 'misspelt');
// Review checks no ruling names (same rule as "Read the reviewer's answer").
const named = (detail, s) => {
  const d = String(detail ?? '').toLowerCase();
  const n = String(s).toLowerCase();
  return d === n || d.includes(`"${n}"`);
};
const unruled = (r) =>
  r.checks.filter((c) => {
    if (c.severity !== 'review') return false;
    if (c.code === 'unmatched_skill') return !r.review.factRulings.some((f) => named(c.detail, f.text));
    if (c.code === 'possible_misspelling') return !r.review.spellingRulings.some((s) => named(c.detail, s.word));
    return true;
  });
const problems = (r) => hard(r).length + unruled(r).length + failedItems(r).length + invented(r).length;

// The passing round, else the one with the fewest problems (ties: the latest).
let best = [...rounds].reverse().find((r) => r.passed === true) ?? null;
if (!best) for (const r of rounds) if (!best || problems(r) <= problems(best)) best = r;
const w = best.writer;
const check = (c) => ({ source: 'check', code: c.code, severity: c.severity, doc: c.doc, ...(c.where ? { where: c.where } : {}), detail: c.detail });
const unresolved = [
  ...hard(best).map(check),
  ...unruled(best).map((c) => ({ ...check(c), note: 'The reviewer did not rule on this.' })),
  ...failedItems(best).map((i) => ({ source: 'review', id: i.id, note: i.note })),
  ...invented(best).map((f) => ({ source: 'fact', text: f.text, why: f.why })),
  ...misspelt(best).map((s) => ({ source: 'spelling', word: s.word, fix: s.fix })),
  ...best.checks.filter((c) => c.severity === 'warning').map(check),
];
// Stretches from the writer and the reviewer, each once.
const seen = new Set();
const stretches = [...(w.stretches ?? []), ...(best.review.stretches ?? [])].filter((s) => {
  const key = `${s.target}\u0000${s.text}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});
return {
  json: {
    run_id,
    claimed_at,
    template_id: w.templateId,
    cv: w.cv,
    cover_letter: w.coverLetter,
    keyword_coverage: w.keywordCoverage,
    checks: best.checks,
    review: { passed: best.passed === true, rounds: rounds.length, verdicts: rounds.map((r) => r.review.verdict), unresolved },
    reasons: { templateReason: w.templateReason, changes: w.changes, stretches, factRulings: best.review.factRulings },
    base_cv_id: inputs.cv_id,
    base_cv_hash: inputs.cv_hash,
    base_cover_letter_id: inputs.cl_id,
    base_cover_letter_hash: inputs.cl_hash,
  },
};

// A node after the claim failed unexpectedly (a safety check that stops the run, a database error).
// End this attempt now, the normal way, instead of leaving the run in_progress until the 6-minute
// stuck check. The run is only touched if it still carries a claim token this execution held: which
// token is current depends on where the error happened, so every one is offered.
const run = $('Claim one run').first().json;
const tokens = [];
const collect = (node) => {
  for (let i = 0; i < 50; i++) {
    let items;
    try {
      items = node.all(0, i);
    } catch {
      break;
    }
    for (const it of items ?? []) if (typeof it.json.claimed_at === 'string') tokens.push(it.json.claimed_at);
  }
};
collect($('Claim one run'));
collect($('Heartbeat: writing'));
collect($('Heartbeat: checking'));
collect($('Heartbeat: reviewing'));
collect($('Record the round'));
const first = $input.first()?.json ?? {};
const raw = typeof first.error === 'string' ? first.error : first.error?.message ?? first.message ?? '';
const detail = String(raw).slice(0, 200);
return [
  {
    json: {
      run_id: run.id ?? null,
      tokens: [...new Set(tokens)],
      error: `Generation hit an unexpected error${detail ? ` (${detail})` : ''}.`,
    },
  },
];
